#This R script is for analysing data from the IBioIC MSc essential skills lab
#Data were generated by pipetting set volumes of water, ethanol, and glycerol solutions
#these volumes were weighed using an analytical balance, and data recorded in PipettingCalibrationCurve.csv

#For each of the liquids pipetted, we wish to generate a standard curve (we will use ggplot2 to plot this)
#we will also generate a linear model using the lm() function

#First, load the necessary libraries (install first, if they are not already there)

library(tidyverse)
library(ggplot2)

# Read in the data from our calibration curve, assigning it to a variable called PipetteData
# It is good practice here to specify the column types (factor and doubles)
PipetteData <- read_csv("PipettingCalibrationCurve.csv",
                        col_types="fdddd")

#examine the data
str(PipetteData)
head(PipetteData)

#To make it easier to work with this data, we will want to convert it to a "long" format

LongData <- pivot_longer(PipetteData, cols = starts_with("Replicate"),
             names_to = "Replicate",
             values_to = "Mass")

#examine the pivoted data to check if it is all right
str(LongData)
head(LongData)

#Plot the data using ggplot2

ggplot(data = LongData, mapping = aes(x=Volume, #define the data we will be using and define aesthetics - Volume on the x-axis
                                      y=Mass, #Mass on the y-axis
                                      colour = Solution)) + #colour based on Solution
  geom_point() + #plot the data points
  geom_smooth(method = "lm") #fit and plot a linear regression

#This looks fairly reasonable but can be cleaned up somewhat, e.g.:

ggplot(data = LongData, mapping = aes(x=Volume, 
                                      y=Mass,
                                      colour = Solution)) +
  geom_point(alpha=0.5) + #make the points partially transparent so that the data can be seen more easily
  geom_smooth(method = "lm") +
  labs(x="Volume dispensed (uL)",
       y="Mass (mg)") + #add more informative axis labels
  theme_classic() #use a classic theme (other themes are available)


#Let's use the linear model function explicitly
#we want to model mass as a function of volume (Mass ~ Volume)
#For the glycerol data:
glycerol_model <- lm(Mass ~ Volume, data = filter(LongData, Solution == "Glycerol"))

summary(glycerol_model)

#For the ethanol data:
ethanol_model <- lm(Mass ~ Volume, data = filter(LongData, Solution == "Ethanol"))

summary(ethanol_model)

#For the water data:
water_model <- lm(Mass ~ Volume, data = filter(LongData, Solution == "Water"))

summary(water_model)

